def rle(s):
    if not s:
        return ""

    encoded = []
    count = 0
    current_char = s[0]

    for char in s:
        if char == current_char:
            count += 1
        else:
            encoded.append(f"{current_char}{count}")
            current_char = char
            count = 1

    encoded.append(f"{current_char}{count}")
    return "".join(encoded)
